def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    o=[r[:] for r in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if (i in (r0,r1) or j in (c0,c1)) and o[i][j]==bg:
                o[i][j]=2
    for i in range(r0+1,r1):
        marks=[j for j in range(c0,c1+1) if g[i][j]!=bg]
        if len(marks)>=3:
            for a,b in zip(marks,marks[1:]):
                for j in range(a+1,b):
                    if o[i][j]==bg: o[i][j]=2
    return o
